function lazyProxy() {
  const target = {};
  const handler = {
    get(target, prop) {
      function* lazyGen() {
        yield `Lazy value for ${prop}`;
      }
      return lazyGen().next().value;
    }
  };
  return new Proxy(target, handler);
}

